'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = input[0];
const K = input[1];
const a = input.slice(2, 2 + N);
const b = input.slice(2 + N, 2 + 2 * N);

let answer = 0;
const bonuses = [];

for (let i = 0; i < N; i++) {
  answer += Math.max(0, a[i] - b[i]);
  bonuses.push(Math.min(a[i], b[i]));
}

bonuses.sort((x, y) => y - x);

for (let i = 0; i < Math.min(N, K + 1); i++) {
  answer += bonuses[i];
}

console.log(answer);
